  const PLOT_CATEGORY_MAIN_ID = "pc-main";
  const PLOT_CATEGORY_ARCHIVE_ID = "pc-archive";
  const FIXED_PLOT_CATEGORY_DEFS = [
    { id: PLOT_CATEGORY_MAIN_ID, name: "进行中的故事" },
    { id: PLOT_CATEGORY_ARCHIVE_ID, name: "归档" },
  ];
  let plotCategories = FIXED_PLOT_CATEGORY_DEFS.map(function (x) {
    return { id: x.id, name: x.name, fixed: true };
  });
  /** 剧情「不分类」：仅出现在「全部」筛选下，不属于任何剧情分类标签 */
  const PLOT_CATEGORY_UNASSIGNED = "";

  function isPlotBuiltinSealCategory(id) {
    return id === PLOT_CATEGORY_MAIN_ID || id === PLOT_CATEGORY_ARCHIVE_ID;
  }

  function ensureFixedPlotCategory() {
    FIXED_PLOT_CATEGORY_DEFS.forEach(function (def, idx) {
      const found = plotCategories.find(function (c) {
        return c && c.id === def.id;
      });
      if (!found) {
        plotCategories.splice(idx, 0, { id: def.id, name: def.name, fixed: true });
        return;
      }
      found.name = def.name;
      found.fixed = true;
    });
  }

  /** 用户可手动指定的剧情分类（不含按封笔自动归类的系统分类） */
  function plotUserAssignableCategories() {
    return plotCategories.filter(function (c) {
      return c && !isPlotBuiltinSealCategory(c.id);
    });
  }

  function defaultPlotUserCategoryId() {
    const user = plotUserAssignableCategories();
    if (user.length) return user[0].id;
    return PLOT_CATEGORY_UNASSIGNED;
  }

  function normalizePlotUserCategoryId(cid) {
    if (cid === PLOT_CATEGORY_UNASSIGNED || cid == null || String(cid).trim() === "") {
      return PLOT_CATEGORY_UNASSIGNED;
    }
    const s = String(cid).trim();
    if (isPlotBuiltinSealCategory(s)) return PLOT_CATEGORY_UNASSIGNED;
    if (plotUserAssignableCategories().some(function (c) {
      return c.id === s;
    })) {
      return s;
    }
    return defaultPlotUserCategoryId();
  }

  /** 列表筛选：进行中=未封笔，归档=已封笔，其余=用户自定义 categoryId */
  function plotMatchesFilter(p, filterId) {
    if (!p) return false;
    if (filterId === "all") return true;
    if (filterId === PLOT_CATEGORY_MAIN_ID) return !p.playSealed;
    if (filterId === PLOT_CATEGORY_ARCHIVE_ID) return !!p.playSealed;
    return String(p.categoryId || "") === String(filterId);
  }

  function resolveNewPlotCategoryId(preferredId) {
    const id = preferredId != null ? String(preferredId).trim() : "";
    if (
      id &&
      id !== "all" &&
      !isPlotBuiltinSealCategory(id) &&
      plotUserAssignableCategories().some(function (c) {
        return c.id === id;
      })
    ) {
      return id;
    }
    return normalizePlotUserCategoryId(id);
  }

  let charCategories = FIXED_CHAR_CATEGORY_DEFS.map(function (x) {
    return { id: x.id, name: x.name, fixed: true };
  });

  let appearanceState = { modeSetting: "system", paletteId: APPEARANCE_PALETTE_DEFAULT_ID };

  /** 浅色 / 深色：跟随系统时用 prefers-color-scheme，否则用手动选择。 */
  function resolveEffectiveThemeMode() {
    if (appearanceState.modeSetting === "system") {
      try {
        return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      } catch (e) {
        return "light";
      }
    }
    return appearanceState.modeSetting === "dark" ? "dark" : "light";
  }
  let customThemePalette = null;
  let customFontMeta = null;
  let loadedFontFace = null;

  function sanitizeThemePaletteTones(rawTones) {
    if (!Array.isArray(rawTones) || rawTones.length < 3) return null;
    const tones = rawTones
      .slice(0, 3)
      .map(function (tone) {
        return normalizeHex(tone);
      })
      .filter(Boolean);
    if (tones.length !== 3) return null;
    return tones;
  }

  function buildCustomThemePalette(rawTones) {
    const tones = sanitizeThemePaletteTones(rawTones);
    if (!tones) return null;
    return {
      id: APPEARANCE_PALETTE_CUSTOM_ID,
      name: "自定义",
      enName: "Custom",
      tones: tones,
    };
  }

  function getThemePalettes() {
    if (!customThemePalette) return THEME_PALETTES.slice();
    return THEME_PALETTES.concat([customThemePalette]);
  }

  function getThemePaletteMap() {
    return getThemePalettes().reduce(function (acc, item) {
      acc[item.id] = item;
      return acc;
    }, {});
  }

  function clampUnit(v) {
    if (!Number.isFinite(v)) return 0;
    return Math.max(0, Math.min(1, v));
  }

  function mixHex(hexA, hexB, weightA) {
    const a = hexToRgb(hexA);
    const b = hexToRgb(hexB);
    if (!a || !b) return normalizeHex(hexA) || normalizeHex(hexB) || "#000000";
    const t = clampUnit(weightA);
    const r = Math.round(a.r * t + b.r * (1 - t));
    const g = Math.round(a.g * t + b.g * (1 - t));
    const bCh = Math.round(a.b * t + b.b * (1 - t));
    const n = (r << 16) | (g << 8) | bCh;
    return "#" + n.toString(16).padStart(6, "0");
  }

  function toRgba(hex, alpha) {
    const c = hexToRgb(hex);
    if (!c) return "rgba(0, 0, 0, " + clampUnit(alpha).toFixed(3) + ")";
    return "rgba(" + c.r + ", " + c.g + ", " + c.b + ", " + clampUnit(alpha).toFixed(3) + ")";
  }

  function resolvePaletteId(rawId) {
    const paletteMap = getThemePaletteMap();
    if (rawId && paletteMap[rawId]) return rawId;
    return APPEARANCE_PALETTE_DEFAULT_ID;
  }

  function buildPaletteCssVars(paletteId, mode) {
    const id = resolvePaletteId(paletteId);
    if (id === APPEARANCE_PALETTE_DEFAULT_ID) return null;
    const p = getThemePaletteMap()[id];
    if (!p || !Array.isArray(p.tones) || p.tones.length < 3) return null;
    const mid = p.tones[0];
    const base = p.tones[1];
    const deep = p.tones[2];
    if (mode === "dark") {
      const accent = mixHex(deep, "#a7a7b4", 0.86);
      const solidFill = mixHex(deep, "#2a2a31", 0.68);
      const shellBg = mixHex("#121214", deep, 0.86);
      return {
        "--palette-mid": mid,
        "--bg": shellBg,
        "--surface": toRgba(mixHex("#202025", mid, 0.72), 0.58),
        "--border": toRgba(mixHex("#d4d7e1", mid, 0.28), 0.2),
        "--text": mixHex("#f0f0f0", base, 0.88),
        "--muted": mixHex("#a3a3a3", base, 0.84),
        "--muted2": mixHex("#8a8a8a", mid, 0.86),
        "--accent": accent,
        "--accent-contrast": pickContrastForAccent(accent),
        "--solid-fill-bg": solidFill,
        "--solid-fill-fg": pickContrastForAccent(solidFill),
        "--solid-fill-border": toRgba(mixHex(deep, "#ffffff", 0.5), 0.32),
        "--glass-bg": toRgba(mixHex("#2a2a2d", mid, 0.72), 0.56),
        "--glass-border": toRgba(mixHex("#ffffff", base, 0.34), 0.22),
        "--glass-edge": toRgba(mixHex("#ffffff", mid, 0.26), 0.16),
        "--glass-shadow": "0 6px 28px rgba(0, 0, 0, 0.45)",
        "--phone-screen-start": shellBg,
        "--phone-screen-end": shellBg,
        "--wb-tag-bg": deep,
        "--wb-tag-fg": pickContrastForAccent(deep),
        "--wb-tag-border": toRgba(mixHex(deep, "#000000", 0.7), 0.42),
      };
    }
    const accent = deep;
    const shellBg = mixHex(base, "#ffffff", 0.84);
    return {
      "--palette-mid": mid,
      "--bg": shellBg,
      "--surface": toRgba(mixHex(base, "#ffffff", 0.72), 0.62),
      "--border": toRgba(mixHex(deep, "#2a2a2a", 0.2), 0.16),
      "--text": mixHex(deep, "#1a1a1a", 0.25),
      "--muted": mixHex(deep, "#6b6b6b", 0.24),
      "--muted2": mixHex(mid, "#707070", 0.24),
      "--accent": accent,
      "--accent-contrast": pickContrastForAccent(accent),
      "--solid-fill-bg": mixHex(deep, "#ffffff", 0.93),
      "--solid-fill-fg": pickContrastForAccent(mixHex(deep, "#ffffff", 0.93)),
      "--solid-fill-border": toRgba(mixHex(deep, "#1a1a1a", 0.4), 0.26),
      "--glass-bg": toRgba(mixHex(base, mid, 0.56), 0.56),
      "--glass-border": toRgba(mixHex(base, "#ffffff", 0.8), 0.74),
      "--glass-edge": toRgba(mixHex(deep, base, 0.34), 0.14),
      "--glass-shadow": "0 4px 24px rgba(0, 0, 0, 0.06)",
      "--phone-screen-start": shellBg,
      "--phone-screen-end": shellBg,
      "--wb-tag-bg": deep,
      "--wb-tag-fg": pickContrastForAccent(deep),
      "--wb-tag-border": toRgba(mixHex(deep, "#1a1a1a", 0.4), 0.3),
    };
  }

  function normalizeHex(input) {
    if (!input || typeof input !== "string") return null;
    let s = input.trim();
    if (!s) return null;
    if (s.startsWith("#")) s = s.slice(1);
    if (s.length === 3) {
      s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
    }
    if (!/^[0-9a-fA-F]{6}$/.test(s)) return null;
    return "#" + s.toLowerCase();
  }

  function hexToRgb(hex) {
    const h = normalizeHex(hex);
    if (!h) return null;
    const n = parseInt(h.slice(1), 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }

  function relativeLuminance(hex) {
    const c = hexToRgb(hex);
    if (!c) return 0;
    const lin = (v) => {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    };
    const R = lin(c.r);
    const G = lin(c.g);
    const B = lin(c.b);
    return 0.2126 * R + 0.7152 * G + 0.0722 * B;
  }

  function pickContrastForAccent(hex) {
    return relativeLuminance(hex) > 0.55 ? "#0a0a0a" : "#ffffff";
  }

  function applyAppearanceToDom() {
    const effectiveMode = resolveEffectiveThemeMode();
    document.documentElement.dataset.theme = effectiveMode;
    appearanceState.paletteId = resolvePaletteId(appearanceState.paletteId);
    document.documentElement.dataset.palette = appearanceState.paletteId;
    APPEARANCE_DYNAMIC_VARS.forEach(function (name) {
      document.documentElement.style.removeProperty(name);
    });
    const paletteVars = buildPaletteCssVars(appearanceState.paletteId, effectiveMode);
    if (!paletteVars) return;
    Object.keys(paletteVars).forEach(function (key) {
      document.documentElement.style.setProperty(key, paletteVars[key]);
    });
    const paletteMap = getThemePaletteMap();
    const palette = paletteMap[appearanceState.paletteId] || paletteMap[APPEARANCE_PALETTE_DEFAULT_ID];
    const marker = palette && Array.isArray(palette.tones) && palette.tones[0] ? normalizeHex(palette.tones[0]) : "#f5d97f";
    document.documentElement.style.setProperty("--story-selection-marker", marker || "#f5d97f");
    document.documentElement.style.setProperty("--story-selection-marker-soft", toRgba(marker || "#f5d97f", 0.36));
    refreshStoryPlayBackgroundForCurrentPlot();
    syncThemeColorMeta();
  }

  function syncThemeColorMeta() {
    const meta = document.querySelector('meta[name="theme-color"]');
    if (!meta) return;
    const bg = getComputedStyle(document.documentElement).getPropertyValue("--bg").trim();
    if (bg) meta.setAttribute("content", bg);
  }

  /** 切换浅色/深色后刷新剧情正文区背景（若当前打开了剧情）。 */
  function refreshStoryPlayBackgroundForCurrentPlot() {
    const layer = els.layerStory();
    if (!layer || layer.hidden) return;
    const plot = plots.find(function (x) {
      return x.id === lastStoryPlotId;
    });
    if (plot) applyStoryBackground(plot);
  }

  function persistAppearance() {
    try {
      localStorage.setItem(
        STORAGE_APPEARANCE,
        JSON.stringify({
          modeSetting: appearanceState.modeSetting,
          paletteId: appearanceState.paletteId,
          customPaletteTones: customThemePalette && Array.isArray(customThemePalette.tones) ? customThemePalette.tones : null,
        })
      );
    } catch (e) {}
  }

  function loadAppearance() {
    try {
      const raw = localStorage.getItem(STORAGE_APPEARANCE);
      if (raw) {
        const o = JSON.parse(raw);
        customThemePalette = buildCustomThemePalette(o.customPaletteTones);
        let migratedLegacyAppearance = false;
        let ms = o.modeSetting;
        if (ms !== "system" && ms !== "light" && ms !== "dark") {
          migratedLegacyAppearance = true;
          if (o.mode === "dark" || o.mode === "light") ms = o.mode;
          else ms = "light";
        }
        appearanceState.modeSetting = ms;
        appearanceState.paletteId = resolvePaletteId(o.paletteId);
        if (migratedLegacyAppearance) persistAppearance();
      }
    } catch (e) {}
    applyAppearanceToDom();
  }

  let systemThemeMediaBound = false;
  function initSystemThemeListener() {
    if (systemThemeMediaBound) return;
    systemThemeMediaBound = true;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onSchemeChange = function () {
      if (appearanceState.modeSetting !== "system") return;
      applyAppearanceToDom();
      try {
        renderDynamic();
      } catch (e) {}
    };
    if (mq.addEventListener) mq.addEventListener("change", onSchemeChange);
    else if (mq.addListener) mq.addListener(onSchemeChange);
  }

  const GLOBAL_GEN_PAW_MODAL_IDS = [
    "modal-assistant-theme",
    "modal-assistant-rewrite",
    "modal-assistant-gen-wb",
    "modal-assistant-plot-reply",
    "modal-assistant-switch",
  ];
  const globalGenPawCounts = Object.create(null);
  let globalGenPawKeyStack = [];
  let globalGenPawWatchHandle = 0;
  let pendingGenCallContext = null;
  /** API 已成功但业务尚未收尾时暂存，在 clearGenCallContext 后统一弹出（与加载态同步） */
  let deferredGenReadyNotice = null;
  let genReadyBannerEl = null;
  let genReadyBannerTimer = 0;

  function totalGlobalGenPawActive() {
    let n = 0;
    for (const k in globalGenPawCounts) {
      if (Object.prototype.hasOwnProperty.call(globalGenPawCounts, k)) n += globalGenPawCounts[k];
    }
    return n;
  }

  function getGlobalGenPawContext() {
    for (let i = 0; i < GLOBAL_GEN_PAW_MODAL_IDS.length; i++) {
      const id = GLOBAL_GEN_PAW_MODAL_IDS[i];
      const modal = document.getElementById(id);
      if (modal && !modal.hidden) {
        const root = modal.querySelector(".modal-sheet") || modal;
        return { key: "modal:" + id, root: root };
      }
    }
    const modalStoryPhone = document.getElementById("modal-story-phone");
    if (modalStoryPhone && !modalStoryPhone.hidden) {
      const slot = document.getElementById("story-phone-slot");
      const nav = getPhoneNav(slot);
      return {
        key: "story:phone:" + phoneNavContextKey(nav),
        root: resolveGenPawRootFromSlot(slot) || slot,
      };
    }
    const modalStoryFanwork = document.getElementById("modal-story-fanwork");
    if (modalStoryFanwork && !modalStoryFanwork.hidden) {
      const slot = document.getElementById("story-fanwork-slot");
      const nav = getFanworkNav(slot);
      return {
        key: "story:fanwork:" + fanworkNavContextKey(nav),
        root: resolveGenPawRootFromSlot(slot) || slot,
      };
    }
    const layerStory = document.getElementById("layer-story");
    if (layerStory && !layerStory.hidden) {
      const playPanel = document.getElementById("story-panel-play");
      const setupPanel = document.getElementById("story-panel-setup");
      let root = layerStory;
      let sub = "layer";
      if (playPanel && !playPanel.hidden) {
        root = playPanel;
        sub = "play";
      } else if (setupPanel && !setupPanel.hidden) {
        root = setupPanel;
        sub = "setup";
      }
      const pid = lastStoryPlotId || "unknown";
      return { key: "story:" + pid + ":" + sub, root: root };
    }
    if (activeTab === "overview") {
      if (overviewSubView === "phone") {
        const slot = document.getElementById("phone-content-slot");
        const ctx = buildPhonePawContext(slot);
        return { key: "overview:" + ctx.key, root: ctx.root };
      }
      if (overviewSubView === "fanwork") {
        const slot = document.getElementById("fanwork-content-slot");
        const ctx = buildFanworkPawContext(slot);
        return { key: "overview:" + ctx.key, root: ctx.root };
      }
      if (overviewSubView === "knock") {
        const slot = document.getElementById("knock-content-slot");
        return { key: "overview:knock", root: slot || document.getElementById("view-overview") };
      }
      return { key: "overview:hub", root: document.getElementById("view-overview") };
    }
    const view = document.getElementById("view-" + activeTab);
    return { key: "tab:" + activeTab, root: view || document.getElementById("main-scroll") };
  }

  function setGenCallContext(ctx) {
    pendingGenCallContext = ctx || null;
  }

  function clearGenCallContext() {
    pendingGenCallContext = null;
    flushDeferredGenReadyBanner();
  }

  function stashGenReadyNotice(notice) {
    if (notice && notice.message) deferredGenReadyNotice = notice;
  }

  /** 在 finally 收尾（关 loading、render）之后再弹出「已生成好」横幅 */
  function flushDeferredGenReadyBanner() {
    if (!deferredGenReadyNotice) return;
    const notice = deferredGenReadyNotice;
    deferredGenReadyNotice = null;
    setTimeout(function () {
      showGenReadyBanner(notice);
    }, 0);
  }

  function buildGenReadyPawSvg() {
    return (
      '<svg class="gen-ready-banner__paw-icon" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">' +
      '<ellipse cx="10" cy="14.5" rx="3.4" ry="2.6"/>' +
      '<circle cx="6.2" cy="8.2" r="1.9"/><circle cx="10" cy="6.8" r="1.9"/>' +
      '<circle cx="13.8" cy="8.2" r="1.9"/><circle cx="7.8" cy="11.2" r="1.55"/>' +
      "</svg>"
    );
  }

  function dismissGenReadyBanner() {
    if (genReadyBannerTimer) {
      clearTimeout(genReadyBannerTimer);
      genReadyBannerTimer = 0;
    }
    if (!genReadyBannerEl) return;
    genReadyBannerEl.classList.remove("gen-ready-banner--show");
    const el = genReadyBannerEl;
    genReadyBannerEl = null;
    setTimeout(function () {
      if (el.parentNode) el.parentNode.removeChild(el);
    }, 280);
  }

  function triggerGenReadyNavigate(notice) {
    dismissGenReadyBanner();
    if (typeof notice.navigate !== "function") return;
    try {
      notice.navigate();
    } catch (err) {
      console.error(err);
      showToast("无法打开生成结果，请手动进入对应页面。", "warning");
    }
  }

  function showGenReadyBanner(notice) {
    if (!notice || !notice.message) return;
    dismissGenReadyBanner();
    const shell = document.getElementById("app-shell");
    if (!shell) return;
    const el = document.createElement("div");
    el.className = "gen-ready-banner";
    el.setAttribute("role", "button");
    el.setAttribute("aria-label", "前往查看：" + String(notice.message));
    el.tabIndex = 0;
    el.innerHTML =
      '<span class="gen-ready-banner__text">' +
      escapeHtml(String(notice.message)) +
      '</span><span class="gen-ready-banner__paw" aria-hidden="true">' +
      buildGenReadyPawSvg() +
      "</span>";
    el.addEventListener("click", function () {
      triggerGenReadyNavigate(notice);
    });
    el.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        triggerGenReadyNavigate(notice);
      }
    });
    shell.appendChild(el);
    genReadyBannerEl = el;
    requestAnimationFrame(function () {
      el.classList.add("gen-ready-banner--show");
    });
    genReadyBannerTimer = setTimeout(dismissGenReadyBanner, 5000);
  }

  function reopenStoryLayerIfHidden() {
    const layerStory = document.getElementById("layer-story");
    if (!layerStory || !layerStory.hidden) return;
    const pid = lastStoryPlotId || phoneHolderPlotId;
    if (!pid) return;
    const plot = plots.find(function (p) {
      return p.id === pid;
    });
    if (!plot) return;
    openStoryLayer(plot, plot.storyEntered ? "play" : "setup");
  }

  function dismissStoryLayerForOverview() {
    const layerStory = document.getElementById("layer-story");
    if (!layerStory || layerStory.hidden) return;
    closeStoryLayer("overview");
  }

  function resolveGenCallExtras(opts) {
    opts = opts && typeof opts === "object" ? opts : {};
    const pending = pendingGenCallContext || {};
    return {
      pawContext: opts.pawContext || pending.pawContext || getGlobalGenPawContext(),
      genReady: opts.genReady || pending.genReady || null,
    };
  }

  function ensureGlobalGenPawContextWatch() {
    if (globalGenPawWatchHandle) return;
    function tick() {
      if (totalGlobalGenPawActive() <= 0) {
        globalGenPawWatchHandle = 0;
        return;
      }
      syncGlobalGenPawOverlay();
      globalGenPawWatchHandle = requestAnimationFrame(tick);
    }
    globalGenPawWatchHandle = requestAnimationFrame(tick);
  }

  function syncGlobalGenPawOverlay() {
    const el = document.getElementById("global-gen-paw-overlay");
    if (!el) return;
    const current = getGlobalGenPawContext();
    const count = globalGenPawCounts[current.key] || 0;
    const show = count > 0;
    if (show && current.root) {
      current.root.classList.add("global-gen-paw-host");
      if (el.parentNode !== current.root) current.root.appendChild(el);
    } else {
      const fallback = document.getElementById("app-shell");
      if (fallback && el.parentNode !== fallback) fallback.appendChild(el);
    }
    el.hidden = !show;
    el.setAttribute("aria-hidden", show ? "false" : "true");
  }

  function beginGlobalGenPawOverlay(ctxOpt) {
    const ctx = ctxOpt || getGlobalGenPawContext();
    globalGenPawCounts[ctx.key] = (globalGenPawCounts[ctx.key] || 0) + 1;
    globalGenPawKeyStack.push(ctx.key);
    syncGlobalGenPawOverlay();
    ensureGlobalGenPawContextWatch();
  }

  function endGlobalGenPawOverlay() {
    const key = globalGenPawKeyStack.pop();
    if (!key) return;
    globalGenPawCounts[key] = Math.max(0, (globalGenPawCounts[key] || 0) - 1);
    if (globalGenPawCounts[key] === 0) delete globalGenPawCounts[key];
    syncGlobalGenPawOverlay();
  }

  function showToast(message, type, duration) {
    type = type || "info";
    duration = duration == null ? 6000 : duration;
    const container = document.getElementById("toast-container");
    if (!container) return;
    const toast = document.createElement("div");
    toast.className = "toast toast--" + type;
    toast.textContent = message;
    container.appendChild(toast);
    requestAnimationFrame(function () {
      toast.classList.add("toast--show");
    });
    setTimeout(function () {
      toast.classList.remove("toast--show");
      setTimeout(function () {
        if (toast.parentNode) toast.parentNode.removeChild(toast);
      }, 300);
    }, duration);
  }

  function idbOpen() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(IDB_NAME, 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(IDB_STORE)) {
          req.result.createObjectStore(IDB_STORE);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  function idbPutFont(buffer) {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).put(buffer, "userFont");
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        })
    );
  }

  function idbGetFont() {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readonly");
          const r = tx.objectStore(IDB_STORE).get("userFont");
          r.onsuccess = () => resolve(r.result);
          r.onerror = () => reject(r.error);
        })
    );
  }

  function idbDeleteFont() {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).delete("userFont");
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        })
    );
  }

  /** @returns {Promise<string|null>} */
  function idbGetNarrativeJson() {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readonly");
          const r = tx.objectStore(IDB_STORE).get(IDB_NARRATIVE_KEY);
          r.onsuccess = () => {
            var v = r.result;
            if (typeof v === "string") resolve(v);
            else resolve(null);
          };
          r.onerror = () => reject(r.error);
        })
    );
  }

  /** @returns {Promise<void>} */
  function idbPutNarrativeJson(s) {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).put(String(s), IDB_NARRATIVE_KEY);
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        })
    );
  }

  /** @returns {Promise<void>} */
  function idbDeleteNarrativeJson() {
    return idbOpen().then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.objectStore(IDB_STORE).delete(IDB_NARRATIVE_KEY);
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        })
    );
  }

  function formatApproxStoredBytes(bytes) {
    const n = typeof bytes === "number" ? bytes : parseInt(bytes, 10);
    if (!Number.isFinite(n) || n < 0) return "未知体积";
    if (n === 0) return "0 B";
    if (n < 1024) return n + " B";
    if (n < 1024 * 1024) return (n / 1024).toFixed(n < 10 * 1024 ? 1 : 0) + " KB";
    return (n / (1024 * 1024)).toFixed(n < 10 * 1024 * 1024 ? 2 : 1) + " MB";
  }

  /**
   * 设置页展示用：不等用户打开 DevTools，直接从 IndexedDB 探测自定义字体条目。
   * @returns {Promise<{ buf: ArrayBuffer | null }>}
   */
  async function probeIndexedDbCustomFontBlob() {
    try {
      const buf = await idbGetFont();
      return {
        buf: buf && typeof buf.byteLength === "number" ? buf : null,
      };
    } catch (_e) {
      return { buf: null };
    }
  }

  /**
   * 在「设定 → 字体」里显示 IndexedDB 是否存有文件及体积（库名 hj_narrative_ui / userFont）。
   */
  async function refreshSettingsFontDiagnostics(settingsRoot) {
    const el =
      settingsRoot && settingsRoot.querySelector ? settingsRoot.querySelector("#font-storage-diagnostics") : null;
    if (!el) return;
    el.innerHTML =
      '<span class="font-storage-diagnostics__loading">' + escapeHtml("正在读取本机字体存储…") + "</span>";
    const { buf } = await probeIndexedDbCustomFontBlob();
    const metaName =
      customFontMeta && typeof customFontMeta.name === "string" && customFontMeta.name.trim()
        ? customFontMeta.name.trim()
        : "";
    const lines = [];

    lines.push('<strong>' + escapeHtml("本机字体文件（IndexedDB）") + "</strong>");

    if (buf) {
      lines.push(
        "已保存：键名 <code>userFont</code> · 体积约 <strong>" +
          escapeHtml(formatApproxStoredBytes(buf.byteLength)) +
          "</strong>"
      );
      lines.push(
        "所在库：<code>" +
          escapeHtml(IDB_NAME) +
          "</code> · 仓库：<code>" +
          escapeHtml(IDB_STORE) +
          "</code>"
      );
      if (loadedFontFace)
        lines.push('<span class="font-storage-diagnostics__ok">' + escapeHtml("当前页面已成功载入该字体。") + "</span>");
      else
        lines.push(
          '<span class="font-storage-diagnostics__warn">' +
            escapeHtml("检测到文件，但当前页未能载入字体（可能与格式或无痕模式限制有关）。") +
            "</span>"
        );
      if (!metaName)
        lines.push(
          '<span class="font-storage-diagnostics__warn">' +
            escapeHtml("缺少本地记录的文件名（不影响使用）；导出备份仍可带上字体。") +
            "</span>"
        );
    } else {
      lines.push(escapeHtml("当前未检测到已保存的字体文件（尚未上传或已清除）。"));
      if (metaName)
        lines.push(
          '<span class="font-storage-diagnostics__warn">' +
            escapeHtml(
              "记录里显示使用过「" + metaName + "」，但库里没有对应文件——请重新上传字体，或点「清除自定义字体」重置。"
            ) +
            "</span>"
        );
    }

    el.innerHTML =
      '<p class="font-storage-diagnostics__line">' +
      lines.join('</p><p class="font-storage-diagnostics__line">') +
      "</p>";
  }

  function getBackupLib() {
    if (typeof window.JSZip === "function") return window.JSZip;
    return null;
  }

  /** 参与导出/导入的 localStorage 键（hj- 前缀 + 自定义字体元数据等） */
  function isBackupStorageKey(key) {
    if (!key || typeof key !== "string") return false;
    if (key.indexOf(BACKUP_STORAGE_PREFIX) === 0) return true;
    if (key === FONT_META_KEY) return true;
    return false;
  }

  function collectLocalStorageSnapshot() {
    const out = {};
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (!isBackupStorageKey(key)) continue;
        const val = localStorage.getItem(key);
        if (typeof val === "string") out[key] = val;
      }
    } catch (e) {}
    return out;
  }

  function clearBackupStorageKeys() {
    try {
      const keys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && isBackupStorageKey(key)) keys.push(key);
      }
      keys.forEach(function (k) {
        localStorage.removeItem(k);
      });
    } catch (e) {}
  }

  async function clearAllUserDataExceptApiSettings() {
    suppressUserDataPersistence = true;
    flushPersistNarrative();
    const keepSnapshot = {};
    CLEAR_DATA_KEEP_KEYS.forEach(function (k) {
      try {
        const v = localStorage.getItem(k);
        if (typeof v === "string") keepSnapshot[k] = v;
      } catch (e) {}
    });
    clearBackupStorageKeys();
    CLEAR_DATA_KEEP_KEYS.forEach(function (k) {
      if (Object.prototype.hasOwnProperty.call(keepSnapshot, k)) {
        localStorage.setItem(k, keepSnapshot[k]);
      } else {
        localStorage.removeItem(k);
      }
    });
    try {
      localStorage.setItem(STORAGE_POST_CLEAR_ASSISTANT_V1, "1");
    } catch (e2) {}
    try {
      await idbDeleteFont();
    } catch (e) {}
    try {
      await idbDeleteNarrativeJson();
    } catch (e2) {}
    showToast("数据已清除，正在刷新页面…", "success");
    try {
      location.hash = "#/tab/overview";
    } catch (e) {}
    window.setTimeout(function () {
      location.reload();
    }, 150);
  }

  function formatBackupFilename(ts) {
    const d = new Date(Number.isFinite(ts) ? ts : Date.now());
    const pad = function (n) {
      return String(n).padStart(2, "0");
    };
    const y = d.getFullYear();
    const m = pad(d.getMonth() + 1);
    const day = pad(d.getDate());
    const hh = pad(d.getHours());
    const mm = pad(d.getMinutes());
    const ss = pad(d.getSeconds());
    return "hj-backup-" + y + m + day + "-" + hh + mm + ss + ".zip";
  }

  function triggerDownloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 2500);
  }

  /** 导出备份用的 narrative JSON：优先当前内存（最全），再与 IndexedDB / localStorage 镜像取较新者。 */
  async function collectBackupNarrativeJson() {
    var memNar = null;
    try {
      memNar = serializeNarrativePayload();
    } catch (eMem) {
      memNar = null;
    }
    var idbNar = null;
    var lsNar = null;
    try {
      idbNar = await idbGetNarrativeJson();
    } catch (eIb) {
      idbNar = null;
    }
    try {
      lsNar = localStorage.getItem(STORAGE_NARRATIVE);
    } catch (eLs) {
      lsNar = null;
    }
    var diskNar = pickNewerNarrativeRaw(idbNar, lsNar);
    if (memNar && diskNar) {
      return narrativeBlobSavedAt(memNar) >= narrativeBlobSavedAt(diskNar) ? memNar : diskNar;
    }
    return memNar || diskNar || null;
  }

  async function buildBackupZipBlob() {
    const JSZip = getBackupLib();
    if (!JSZip) throw new Error("JSZIP_MISSING");
    const zip = new JSZip();
    zip.file(
      "manifest.json",
      JSON.stringify(
        {
          format: BACKUP_FORMAT,
          version: BACKUP_VERSION,
          appTitle: "嗅嗅剧场",
          exportedAt: new Date().toISOString(),
          contents: [
            "角色、剧情、世界书及分类",
            "剧情正文/总结/记忆/收藏/划线/想法/背景图",
            "查手机各 App 生成内容与壁纸",
            "小狗饭剧情、分区与作品数据",
            "点星助手、人设与聊天记录",
            "API 配置与密钥",
            "外观主题、亮度、字体与状态栏等设置",
            "自定义字体文件（如有）",
          ],
        },
        null,
        2
      )
    );
    const storageSnap = collectLocalStorageSnapshot();
    try {
      const nar = await collectBackupNarrativeJson();
      if (typeof nar === "string" && nar.length) {
        storageSnap[STORAGE_NARRATIVE] = nar;
        zip.file(BACKUP_NARRATIVE_FILE, nar);
      }
    } catch (_eNar) {}
    zip.file("localStorage.json", JSON.stringify(storageSnap, null, 2));
    let fontBuffer = null;
    try {
      fontBuffer = await idbGetFont();
    } catch (e) {
      fontBuffer = null;
    }
    if (fontBuffer) zip.file("userFont.bin", fontBuffer);
    return zip.generateAsync({
      type: "blob",
      compression: "DEFLATE",
      compressionOptions: { level: 6 },
    });
  }

  async function exportFullBackup() {
    await flushPersistNarrativeAwaitForBackup();
    persistAssistantState();
    persistApiConfigs();
    persistAppearance();
    const JSZip = getBackupLib();
    if (!JSZip) {
      showToast("备份依赖未加载，请刷新页面后重试。", "error");
      return;
    }
    try {
      const blob = await buildBackupZipBlob();
      triggerDownloadBlob(blob, formatBackupFilename(Date.now()));
      showToast("备份已导出到下载目录。", "success");
    } catch (e) {
      showToast("导出备份失败，请稍后重试。", "error");
    }
  }

  function stripJsonUtf8Bom(s) {
    if (typeof s !== "string") return s;
    const t = s.trim();
    if (t.charCodeAt(0) === 0xfeff) return t.slice(1);
    return t;
  }

  function parseBackupStorageJson(raw) {
    const obj = JSON.parse(stripJsonUtf8Bom(String(raw)));
    if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
      throw new Error("BACKUP_STORAGE_INVALID");
    }
    const out = {};
    Object.keys(obj).forEach(function (k) {
      if (!isBackupStorageKey(k)) return;
      const v = obj[k];
      if (typeof v === "string") out[k] = v;
    });
    return out;
  }

  /** 兼容 zip 根路径为「localStorage.json」或「./folder/localStorage.json」等 */
  function zipGetFileInsensitive(zip, wantName) {
    const exact = zip.file(wantName);
    if (exact && !exact.dir) return exact;
    const wantBase = String(wantName || "")
      .split("/")
      .pop()
      .toLowerCase();
    const names = Object.keys(zip.files || {});
    for (let i = 0; i < names.length; i++) {
      const name = names[i];
      const meta = zip.files[name];
      if (!meta || meta.dir) continue;
      const base = name.split("/").pop().toLowerCase();
      if (base === wantBase) return zip.file(name);
    }
    return null;
  }

  function isBackupManifestImportable(manifest) {
    if (!manifest || typeof manifest !== "object") return false;
    if (manifest.format !== BACKUP_FORMAT) return false;
    let v = Number(manifest.version);
    if (!Number.isFinite(v) && manifest.version == null) v = BACKUP_IMPORT_MIN_VERSION;
    if (!Number.isFinite(v)) return false;
    if (v < BACKUP_IMPORT_MIN_VERSION || v > BACKUP_VERSION) return false;
    return true;
  }

  async function applyBackupFromZipFile(file) {
    if (!file) return;
    if (!/\.zip$/i.test(file.name || "")) {
      showToast("请选择 ZIP 格式的备份文件。", "error");
      return;
    }
    if (file.size > BACKUP_IMPORT_MAX_SIZE) {
      showToast("备份文件过大（超过 100MB），请确认后重试。", "error");
      return;
    }
    const JSZip = getBackupLib();
    if (!JSZip) {
      showToast("备份依赖未加载，请刷新页面后重试。", "error");
      return;
    }
    try {
      const zip = await JSZip.loadAsync(file);
      const manifestEntry = zipGetFileInsensitive(zip, "manifest.json");
      const storageEntry = zipGetFileInsensitive(zip, "localStorage.json");
      if (!storageEntry) {
        throw new Error("BACKUP_FILE_MISSING");
      }
      const storageRaw = await storageEntry.async("string");
      const snapshot = parseBackupStorageJson(storageRaw);
      let manifest;
      if (manifestEntry) {
        manifest = JSON.parse(await manifestEntry.async("string"));
      } else {
        if (!Object.keys(snapshot).length) {
          throw new Error("BACKUP_FILE_MISSING");
        }
        manifest = { format: BACKUP_FORMAT, version: BACKUP_IMPORT_MIN_VERSION };
      }
      if (!isBackupManifestImportable(manifest)) {
        throw new Error("BACKUP_MANIFEST_INVALID");
      }
      clearBackupStorageKeys();
      Object.keys(snapshot).forEach(function (k) {
        localStorage.setItem(k, snapshot[k]);
      });
      var importedNar = snapshot[STORAGE_NARRATIVE];
      const narrativeEntry = zipGetFileInsensitive(zip, BACKUP_NARRATIVE_FILE);
      if (narrativeEntry) {
        try {
          const fileNar = await narrativeEntry.async("string");
          importedNar = pickNewerNarrativeRaw(importedNar, fileNar);
        } catch (_eNarFile) {}
      }
      if (typeof importedNar === "string" && importedNar.length) {
        try {
          await idbPutNarrativeJson(importedNar);
        } catch (_eImp) {}
        try {
          localStorage.removeItem(STORAGE_NARRATIVE);
          localStorage.removeItem(STORAGE_NARRATIVE_SYNC_AT);
        } catch (_eLs) {}
      } else {
        try {
          await idbDeleteNarrativeJson();
        } catch (_eDel) {}
      }
      /**
       * 必须立刻禁止持久化并向磁盘 flush：否则会话内存仍是「导入前」的空数据，
       * reload 前的 beforeunload/pagehide 会把空 narrative 写回盖掉刚导入的内容。
       */
      suppressUserDataPersistence = true;
      flushPersistNarrative();
      const fontEntry = zipGetFileInsensitive(zip, "userFont.bin");
      if (fontEntry) {
        const fontBuffer = await fontEntry.async("arraybuffer");
        await idbPutFont(fontBuffer);
      } else {
        await idbDeleteFont();
      }
      showToast("备份导入成功，正在刷新页面…", "success");
      try {
        location.hash = "#/tab/overview";
      } catch (e) {}
      window.setTimeout(function () {
        location.reload();
      }, 150);
    } catch (e) {
      var msg = "导入备份失败：文件无效或已损坏。";
      if (e && e.message === "BACKUP_MANIFEST_INVALID") {
        msg =
          "导入备份失败：备份格式与当前版本不兼容（或 manifest 损坏）。请确认是本应用导出的 hj-backup。";
      } else if (e && e.message === "BACKUP_FILE_MISSING") {
        msg = "导入备份失败：ZIP 内缺少可用的 localStorage.json。";
      } else if (e && e.message === "BACKUP_STORAGE_INVALID") {
        msg = "导入备份失败：localStorage.json 格式不正确。";
      }
      showToast(msg, "error");
    }
  }

  function setFontStackDefault() {
    document.documentElement.style.setProperty("--font-stack", DEFAULT_FONT_STACK);
  }

  function setFontStackCustom() {
    document.documentElement.style.setProperty(
      "--font-stack",
      '"' + FONT_FACE_NAME + '", ' + DEFAULT_FONT_STACK
    );
  }

  async function tryLoadPersistedFont() {
    customFontMeta = null;
    try {
      const metaRaw = localStorage.getItem(FONT_META_KEY);
      if (metaRaw) customFontMeta = JSON.parse(metaRaw);
    } catch (e) {}
    let buf = null;
    try {
      buf = await idbGetFont();
    } catch (e) {
      buf = null;
    }
    if (!buf) {
      setFontStackDefault();
      return;
    }
    try {
      if (loadedFontFace) {
        try {
          document.fonts.delete(loadedFontFace);
        } catch (e2) {}
        loadedFontFace = null;
      }
      const ff = new FontFace(FONT_FACE_NAME, buf);
      const loaded = await ff.load();
      document.fonts.add(loaded);
      loadedFontFace = loaded;
      setFontStackCustom();
    } catch (e) {
      setFontStackDefault();
    }
  }

  async function clearPersistedFont() {
    try {
      await idbDeleteFont();
    } catch (e) {}
    try {
      localStorage.removeItem(FONT_META_KEY);
    } catch (e) {}
    customFontMeta = null;
    if (loadedFontFace) {
      try {
        document.fonts.delete(loadedFontFace);
      } catch (e) {}
      loadedFontFace = null;
    }
    setFontStackDefault();
  }

  function clampUiFontScale(v) {
    const n = typeof v === "number" ? v : parseFloat(v);
    if (!Number.isFinite(n)) return UI_FONT_SCALE_DEFAULT;
    return Math.max(UI_FONT_SCALE_MIN, Math.min(UI_FONT_SCALE_MAX, n));
  }

  function getPersistedUiFontScale() {
    try {
      const raw = localStorage.getItem(STORAGE_UI_FONT_SCALE);
      if (raw == null || raw === "") return UI_FONT_SCALE_DEFAULT;
      return clampUiFontScale(parseFloat(raw));
    } catch (e) {
      return UI_FONT_SCALE_DEFAULT;
    }
  }

  function persistUiFontScale(scale) {
    const s = clampUiFontScale(scale);
    try {
      if (Math.abs(s - UI_FONT_SCALE_DEFAULT) < 0.0001) localStorage.removeItem(STORAGE_UI_FONT_SCALE);
      else localStorage.setItem(STORAGE_UI_FONT_SCALE, String(s));
    } catch (e) {}
  }

  function applyUiFontScaleToDom(scale) {
    const s = clampUiFontScale(scale);
    try {
      document.documentElement.style.setProperty("--hj-font-scale", String(s));
    } catch (e) {}
  }

  function loadUiFontScaleAndApply() {
    applyUiFontScaleToDom(getPersistedUiFontScale());
  }

  function clampUiBrightness(mult) {
    const n = typeof mult === "number" ? mult : parseFloat(mult);
    if (!Number.isFinite(n)) return UI_BRIGHTNESS_DEFAULT;
    return Math.max(UI_BRIGHTNESS_MIN, Math.min(UI_BRIGHTNESS_MAX, n));
  }

  function getPersistedUiBrightness() {
    try {
      const raw = localStorage.getItem(STORAGE_UI_BRIGHTNESS);
      if (raw == null || raw === "") return UI_BRIGHTNESS_DEFAULT;
      return clampUiBrightness(parseFloat(raw));
    } catch (e) {
      return UI_BRIGHTNESS_DEFAULT;
    }
  }

  function persistUiBrightness(mult) {
    const b = clampUiBrightness(mult);
    try {
      if (Math.abs(b - UI_BRIGHTNESS_DEFAULT) < 0.001) localStorage.removeItem(STORAGE_UI_BRIGHTNESS);
      else localStorage.setItem(STORAGE_UI_BRIGHTNESS, String(b));
    } catch (e) {}
  }

  function applyUiBrightnessToDom(mult) {
    const b = clampUiBrightness(mult);
    try {
      document.documentElement.style.setProperty("--hj-ui-brightness", String(b));
    } catch (e) {}
  }

  function loadUiBrightnessAndApply() {
    applyUiBrightnessToDom(getPersistedUiBrightness());
  }

  function formatClockTime(d) {
    const dt = d instanceof Date ? d : new Date();
    return String(dt.getHours()).padStart(2, "0") + ":" + String(dt.getMinutes()).padStart(2, "0");
  }

  function tickStatusClock() {
    const el = document.getElementById("status-time");
    const timeText = formatClockTime(new Date());
    if (el) el.textContent = timeText;
    document.querySelectorAll(".phone-home__clock").forEach(function (clockEl) {
      clockEl.textContent = timeText;
    });
    document.querySelectorAll(".phone-device__time").forEach(function (clockEl) {
      clockEl.textContent = timeText;
    });
  }

  function getStatusBarRightLabel() {
    try {
      const v = localStorage.getItem(STORAGE_STATUS_BAR_RIGHT);
      if (v != null && v !== "") return v;
    } catch (e) {}
    return STATUS_BAR_RIGHT_DEFAULT;
  }

  function applyStatusBarRightLabel() {
    const el = document.getElementById("status-custom-label");
    if (!el || el.tagName !== "INPUT") return;
    el.value = getStatusBarRightLabel();
  }

  function bindStatusBarRightEdit() {
    const input = document.getElementById("status-custom-label");
    if (!input || input.tagName !== "INPUT" || input.dataset.bound) return;
    input.dataset.bound = "1";
    let snapshot = input.value;
    input.addEventListener("focus", function () {
      snapshot = this.value;
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        this.blur();
      } else if (e.key === "Escape") {
        e.preventDefault();
        this.value = snapshot;
        this.blur();
      }
    });
    input.addEventListener("blur", function () {
      const t = String(this.value || "").trim();
      try {
        if (t) localStorage.setItem(STORAGE_STATUS_BAR_RIGHT, t);
        else localStorage.removeItem(STORAGE_STATUS_BAR_RIGHT);
      } catch (e) {}
      this.value = getStatusBarRightLabel();
    });
  }

  function initStatusBar() {
    tickStatusClock();
    setInterval(tickStatusClock, 1000);
    applyStatusBarRightLabel();
    bindStatusBarRightEdit();
  }

  function bindSettingsDelegation() {
    const root = document.getElementById("settings-body");
    if (!root || root.dataset.delegationBound) return;
    root.dataset.delegationBound = "1";

    root.addEventListener("click", (e) => {
      const btn = e.target.closest("button");
      if (!btn || !root.contains(btn)) return;
      if (btn.id === "set-theme-system") {
        appearanceState.modeSetting = "system";
        persistAppearance();
        applyAppearanceToDom();
        renderDynamic();
      }
      if (btn.id === "set-theme-light") {
        appearanceState.modeSetting = "light";
        persistAppearance();
        applyAppearanceToDom();
        renderDynamic();
      }
      if (btn.id === "set-theme-dark") {
        appearanceState.modeSetting = "dark";
        persistAppearance();
        applyAppearanceToDom();
        renderDynamic();
      }
      if (btn.dataset.paletteId) {
        const nextPaletteId = resolvePaletteId(btn.dataset.paletteId);
        if (nextPaletteId === appearanceState.paletteId) return;
        appearanceState.paletteId = nextPaletteId;
        persistAppearance();
        applyAppearanceToDom();
        renderDynamic();
      }
      if (btn.id === "btn-custom-palette-save") {
        const t1Input = root.querySelector("#custom-palette-tone-1");
        const t2Input = root.querySelector("#custom-palette-tone-2");
        const t3Input = root.querySelector("#custom-palette-tone-3");
        const tones = [
          t1Input ? t1Input.value : "",
          t2Input ? t2Input.value : "",
          t3Input ? t3Input.value : "",
        ];
        const built = buildCustomThemePalette(tones);
        if (!built) {
          showToast("请先选择 3 个有效颜色后再应用。", "warning");
          return;
        }
        customThemePalette = built;
        appearanceState.paletteId = APPEARANCE_PALETTE_CUSTOM_ID;
        persistAppearance();
        applyAppearanceToDom();
        renderDynamic();
        showToast("已应用该色板。", "success");
      }
      if (btn.id === "btn-font-clear") {
        clearPersistedFont().then(() => renderDynamic());
      }
      if (btn.id === "btn-backup-export") {
        void exportFullBackup();
      }
      if (btn.id === "btn-backup-import") {
        void (async function () {
          const ok = await showConfirm(
            "导入后会清空并覆盖当前所有本地内容（剧情、角色、世界书、助手聊天、API 与外观设置）。确认继续吗？",
            "导入备份并覆盖"
          );
          if (!ok) return;
          const picker = root.querySelector("#backup-file-input");
          if (!picker) return;
          picker.value = "";
          picker.click();
        })();
      }
      if (btn.id === "btn-clear-user-data") {
        void (async function () {
          const ok = await showConfirm(
            "将清空当前除 API 模型配置外的所有本地数据（剧情、角色、世界书、助手聊天、外观与字体设置等），且不可恢复。确认继续吗？",
            "清除数据"
          );
          if (!ok) return;
          await clearAllUserDataExceptApiSettings();
        })();
      }
    });

    root.addEventListener("change", (e) => {
      const input = e.target;
      if (!input || !input.id) return;
      if (input.id === "backup-file-input") {
        const backupFile = input.files && input.files[0];
        input.value = "";
        if (!backupFile) return;
        void applyBackupFromZipFile(backupFile);
        return;
      }
      if (input.id !== "font-file-input") return;
      const file = input.files && input.files[0];
      input.value = "";
      if (!file) return;
      const ok = /\.(ttf|otf|woff2?)$/i.test(file.name);
      if (!ok) {
        alert("请选择 TTF、OTF、WOFF 或 WOFF2 格式的字体文件。");
        return;
      }
      if (file.size > FONT_UPLOAD_MAX_BYTES) {
        alert("字体文件过大（超过 " + FONT_UPLOAD_MAX_LABEL + "），请换用较小的字体或使用子集字体。");
        return;
      }
      const reader = new FileReader();
      reader.onload = async () => {
        try {
          const buf = reader.result;
          try {
            await idbPutFont(buf);
          } catch (err1) {
            alert("无法保存字体（可能为无痕模式或浏览器禁止 IndexedDB）。请使用普通窗口重试。");
            return;
          }
          localStorage.setItem(FONT_META_KEY, JSON.stringify({ name: file.name }));
          customFontMeta = { name: file.name };
          if (loadedFontFace) {
            try {
              document.fonts.delete(loadedFontFace);
            } catch (err) {}
            loadedFontFace = null;
          }
          const ff = new FontFace(FONT_FACE_NAME, buf);
          const loaded = await ff.load();
          document.fonts.add(loaded);
          loadedFontFace = loaded;
          setFontStackCustom();
          renderDynamic();
        } catch (err) {
          alert("字体加载失败，请尝试其他文件或格式。");
        }
      };
      reader.readAsArrayBuffer(file);
    });

    root.addEventListener("input", (e) => {
      const input = e.target;
      if (!input) return;
      if (input.id === "font-scale-slider") {
        const pct = Number(input.value);
        if (!Number.isFinite(pct)) return;
        const scale = clampUiFontScale(pct / 100);
        persistUiFontScale(scale);
        applyUiFontScaleToDom(scale);
        try {
          input.setAttribute("aria-valuenow", String(Math.round(pct)));
          input.setAttribute("aria-valuetext", Math.round(pct) + "%");
        } catch (errAttr) {}
        const lab = root.querySelector("#font-scale-value");
        if (lab) lab.textContent = Math.round(pct) + "%";
        return;
      }
      if (input.id === "ui-brightness-slider") {
        const pct = Number(input.value);
        if (!Number.isFinite(pct)) return;
        const mult = clampUiBrightness(pct / 100);
        persistUiBrightness(mult);
        applyUiBrightnessToDom(mult);
        try {
          input.setAttribute("aria-valuenow", String(Math.round(pct)));
          input.setAttribute("aria-valuetext", Math.round(pct) + "%");
        } catch (errAttr2) {}
        const labB = root.querySelector("#ui-brightness-value");
        if (labB) labB.textContent = Math.round(pct) + "%";
      }
    });
  }

  let characters = [];

  let worldBooks = [];

  let plots = [];

  /** 每回合「续写内容」目标字数下限（汉字）；影响提示词与 API token；须早于 normalizeItemCategories */
  const DEFAULT_STORY_WORD_LIMIT = 1800;
  /** 剧情总结生成：以写全要点为先；仅当模型输出失控时用 SUMMARY_OUTPUT_HARD_CAP_CHARS 兜底截断 */
  const SUMMARY_OUTPUT_HARD_CAP_CHARS = 24000;
  const PLAY_SUMMARY_REF_LIMIT = 6;
  const PLAY_SUMMARY_ITEM_MAX_CHARS = 12000;
  /** 送入 API 的总结摘录上限（存档仍可用 PLAY_SUMMARY_ITEM_MAX_CHARS 存全文） */
  const PLAY_SUMMARY_PROMPT_ITEM_MAX_CHARS = 4000;
  /** 剧情续写：最近 N 轮正文 + 最新 N 条总结 + N 条相关记忆（单一窗口，便于控制体积） */
  const STORY_PLAY_REF_TURN_LIMIT = 5;
  /** 每轮内部概要：续写时前 N-1 轮用概要、最后一轮用全文；送入模型的单条概要上限 */
  const TURN_DIGEST_PROMPT_MAX_CHARS = 800;
  /** 每轮内部概要存盘/API 生成硬上限 */
  const TURN_DIGEST_STORE_MAX_CHARS = 1200;
  /** 续写送入模型的总结条数（总结已压缩，可略多于正文轮数窗口） */
  const PLAY_SUMMARY_PROMPT_REF_LIMIT = PLAY_SUMMARY_REF_LIMIT;
  /** 剧情续写单次请求的用户/系统提示软上限，避免 Gemini 中转因上下文过大返回 empty_response */
  const STORY_PLAY_API_USER_MAX_CHARS = 30000;
  const STORY_PLAY_API_SYSTEM_MAX_CHARS = 14000;
  const STORY_PLAY_HISTORY_LINE_MAX_CHARS = 900;
  const PLOT_MEMORY_MAX_STORE = 20;
  /** 续写时送入模型的记忆条数（与 STORY_PLAY_REF_TURN_LIMIT 一致） */
  const PLOT_MEMORY_PROMPT_MAX = STORY_PLAY_REF_TURN_LIMIT;
  const PLOT_MEMORY_PROMPT_ITEM_MAX_CHARS = 480;
  const PLOT_MEMORY_CONTEXT_MAX_CHARS = 3800;
  /** 续写 API 用滚动「至今主线」摘录上限（完整阶段总结仍按 PLAY_SUMMARY_ITEM_MAX_CHARS 存盘） */
  const STORY_PLAY_MAINLINE_SUMMARY_MAX_CHARS = 2400;
  /** 已有正文时送入模型的故事开端摘录上限（避免与最近剧情重复占满上下文） */
  const STORY_PLAY_OPENING_WHEN_PLAYING_MAX_CHARS = 520;
  const PLOT_MEMORY_MANDATORY_FROM_SUMMARY = 2;
  const PLOT_MEMORY_MANDATORY_RELEVANT = 3;

  function ensureFixedCharCategory() {
    FIXED_CHAR_CATEGORY_DEFS.forEach(function (def, idx) {
      const found = charCategories.find(function (c) {
        return c && c.id === def.id;
      });
      if (!found) {
        charCategories.splice(idx, 0, { id: def.id, name: def.name, fixed: true });
        return;
      }
      found.name = def.name;
      found.fixed = true;
    });
  }

  /** 是否已有可显示的互动剧情记录（用于修复旧存档缺失 storyEntered 导致刷新被踢回「设定」页） */
  function plotHasRecordedInteractivePlay(p) {
    if (!p || !Array.isArray(p.playTurns)) return false;
    return p.playTurns.some(function (turn) {
      if (!turn) return false;
      const chs = Array.isArray(turn.choices) ? turn.choices : [];
      if (chs.length > 0) return true;
      const lines = Array.isArray(turn.lines) ? turn.lines : [];
      return lines.some(function (ln) {
        return String((ln && ln.text) || "").trim();
      });
    });
  }

  function normalizeItemCategories() {
    ensureFixedCharCategory();
    const defWb = wbCategories[0] && wbCategories[0].id;
    if (defWb) {
      worldBooks.forEach((w) => {
        if (!w.category || !wbCategories.some((c) => c.id === w.category)) w.category = defWb;
      });
    }
    ensureFixedPlotCategory();
    plots.forEach((p) => {
      p.categoryId = normalizePlotUserCategoryId(p.categoryId);
    });
    plots.forEach((p) => {
      if (typeof p.theme !== "string" && typeof p.opening === "string") p.theme = p.opening;
      if (!Array.isArray(p.supportingIds)) p.supportingIds = [];
      if (!Array.isArray(p.supportingNames)) p.supportingNames = [];
      if (typeof p.wordLimit !== "number" || !Number.isFinite(p.wordLimit)) p.wordLimit = DEFAULT_STORY_WORD_LIMIT;
      else if (p.wordLimit === 160 || p.wordLimit === 260 || p.wordLimit === 420 || p.wordLimit === 840 || p.wordLimit === 1200)
        p.wordLimit = DEFAULT_STORY_WORD_LIMIT;
      if (!Number.isFinite(p.lastGeneratedAt)) {
        const legacyTs = typeof p.updated === "number" ? p.updated : Date.parse(String(p.updated || ""));
        p.lastGeneratedAt = Number.isFinite(legacyTs) ? legacyTs : Date.now();
      }
      if (!p.protagonistId && p.charName) {
        const ch = characters.find((c) => c.name === p.charName);
        if (ch) p.protagonistId = ch.id;
      }
      if (!Array.isArray(p.summaryTags)) p.summaryTags = [];
      if (typeof p.eraBackground !== "string") p.eraBackground = "";
      if (typeof p.characterIdentities !== "string") p.characterIdentities = "";
      if (typeof p.characterIdentitySelf !== "string") p.characterIdentitySelf = "";
      if (typeof p.characterIdentityOthers !== "string") p.characterIdentityOthers = "";
      if (typeof p.storyStart !== "string") p.storyStart = "";
      if (typeof p.storyEntered !== "boolean") p.storyEntered = false;
      if (typeof p.playTurnInFlight !== "boolean") p.playTurnInFlight = false;
      if (typeof p.playChoiceExpandInFlight !== "boolean") p.playChoiceExpandInFlight = false;
      if (typeof p.playChoicesRegenerateInFlight !== "boolean") p.playChoicesRegenerateInFlight = false;
      if (typeof p.playSealed !== "boolean") p.playSealed = false;
      if (!p.pendingPlayerTurnAction || typeof p.pendingPlayerTurnAction !== "object") p.pendingPlayerTurnAction = null;
      if (!p.playIntro || typeof p.playIntro !== "object") p.playIntro = { era: "", identities: "", myImage: "", otherRoles: "", opening: "" };
      else {
        if (typeof p.playIntro.era !== "string") p.playIntro.era = "";
        if (typeof p.playIntro.identities !== "string") p.playIntro.identities = "";
        if (typeof p.playIntro.myImage !== "string") p.playIntro.myImage = "";
        if (typeof p.playIntro.otherRoles !== "string") p.playIntro.otherRoles = "";
        if (typeof p.playIntro.opening !== "string") p.playIntro.opening = "";
      }
      if (!p.characterIdentitySelf && !p.characterIdentityOthers && p.characterIdentities) {
        const identSections = splitStoryIdentitySections(p.characterIdentities, p);
        p.characterIdentitySelf = identSections.selfText;
        p.characterIdentityOthers = identSections.othersText;
      }
      if (!p.playIntro.myImage && p.characterIdentitySelf) p.playIntro.myImage = p.characterIdentitySelf;
      if (!p.playIntro.otherRoles && p.characterIdentityOthers) p.playIntro.otherRoles = p.characterIdentityOthers;
      p.characterIdentities = composeStoryIdentityText(p.characterIdentitySelf, p.characterIdentityOthers, p.characterIdentities);
      if (!p.playIntro.identities) p.playIntro.identities = p.characterIdentities;
      if (!Array.isArray(p.playTurns)) p.playTurns = [];
      ensureStoryLineIds(p);
      if (!Array.isArray(p.summaries)) p.summaries = [];
      p.summaries = p.summaries
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          return {
            id: String(it.id || uid("sum")),
            createdAt: Number.isFinite(it.createdAt) ? it.createdAt : Date.now(),
            fromLineId: typeof it.fromLineId === "string" ? it.fromLineId : "",
            toLineId: typeof it.toLineId === "string" ? it.toLineId : "",
            fromTurn: Number.isFinite(it.fromTurn) ? it.fromTurn : 0,
            toTurn: Number.isFinite(it.toTurn) ? it.toTurn : 0,
            content: String(it.content || "").trim(),
            manualEdited: !!it.manualEdited,
            auto: !!it.auto,
          };
        })
        .filter(function (it) {
          return !!it.content;
        });
      if (typeof p.summaryCursorLineId !== "string") p.summaryCursorLineId = "";
      if (typeof p.summaryAutoEnabled !== "boolean") p.summaryAutoEnabled = true;
      if (typeof p.summaryInFlight !== "boolean") p.summaryInFlight = false;
      if (typeof p.phoneStoryDateKey !== "string") p.phoneStoryDateKey = "";
      if (!p.myCharacterOverride || typeof p.myCharacterOverride !== "object") p.myCharacterOverride = null;
      else {
        p.myCharacterOverride = {
          avatarUrl: String(p.myCharacterOverride.avatarUrl || "").trim(),
          profile: String(p.myCharacterOverride.profile || "").trim(),
        };
      }
      if (!Array.isArray(p.characterOverrides)) p.characterOverrides = [];
      p.characterOverrides = p.characterOverrides
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          return {
            characterId: String(it.characterId || "").trim(),
            avatarUrl: String(it.avatarUrl || "").trim(),
            profile: String(it.profile || "").trim(),
          };
        })
        .filter(function (it) {
          return !!it.characterId && (!!it.avatarUrl || !!it.profile);
        });
      if (!Array.isArray(p.memories)) p.memories = [];
      p.memories = p.memories
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          return {
            id: String(it.id || uid("mem")),
            content: String(it.content || "").trim(),
            sourceType:
              it.sourceType === "summary"
                ? "summary"
                : it.sourceType === "line"
                  ? "line"
                  : "manual",
            sourceSummaryId: String(it.sourceSummaryId || "").trim(),
            createdAt: Number.isFinite(it.createdAt) ? it.createdAt : Date.now(),
            updatedAt: Number.isFinite(it.updatedAt) ? it.updatedAt : Date.now(),
          };
        })
        .filter(function (it) {
          return !!it.content;
        });
      if (p.memories.length > PLOT_MEMORY_MAX_STORE) {
        p.memories = p.memories
          .slice()
          .sort(function (a, b) {
            return (b.updatedAt || 0) - (a.updatedAt || 0);
          })
          .slice(0, PLOT_MEMORY_MAX_STORE);
      }
      if (!Array.isArray(p.favorites)) p.favorites = [];
      p.favorites = p.favorites
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          const cid = String(it.characterId || "").trim();
          const kindRaw = String(it.kind || "").trim();
          const kind = kindRaw === "role" || (!kindRaw && cid) ? "role" : "narration";
          return {
            id: String(it.id || uid("fav")),
            content: String(it.content || "").trim(),
            sourceType: it.sourceType === "line" ? "line" : "manual",
            characterId: cid,
            displayName: String(it.displayName || "").trim(),
            avatarUrl: String(it.avatarUrl || "").trim(),
            kind: kind,
            createdAt: Number.isFinite(it.createdAt) ? it.createdAt : Date.now(),
            updatedAt: Number.isFinite(it.updatedAt) ? it.updatedAt : Date.now(),
          };
        })
        .filter(function (it) {
          return !!it.content;
        });
      if (!Array.isArray(p.storyHighlights)) p.storyHighlights = [];
      p.storyHighlights = p.storyHighlights
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          const start = Number.isFinite(it.start) ? Math.max(0, Math.floor(it.start)) : 0;
          const end = Number.isFinite(it.end) ? Math.max(start + 1, Math.floor(it.end)) : start + 1;
          return {
            id: String(it.id || uid("hl")),
            lineId: String(it.lineId || "").trim(),
            start: start,
            end: end,
            text: String(it.text || "").trim(),
            createdAt: Number.isFinite(it.createdAt) ? it.createdAt : Date.now(),
          };
        })
        .filter(function (it) {
          return !!it.lineId && it.end > it.start;
        });
      if (!Array.isArray(p.storyThoughts)) p.storyThoughts = [];
      p.storyThoughts = p.storyThoughts
        .filter(function (it) {
          return it && typeof it === "object";
        })
        .map(function (it) {
          const start = Number.isFinite(it.start) ? Math.max(0, Math.floor(it.start)) : 0;
          const end = Number.isFinite(it.end) ? Math.max(start + 1, Math.floor(it.end)) : start + 1;
          return {
            id: String(it.id || uid("thought")),
            lineId: String(it.lineId || "").trim(),
            start: start,
            end: end,
            quote: String(it.quote || "").trim(),
            content: String(it.content || "").trim(),
            emoji: normalizeStoryThoughtEmoji(it.emoji),
            createdAt: Number.isFinite(it.createdAt) ? it.createdAt : Date.now(),
            updatedAt: Number.isFinite(it.updatedAt) ? it.updatedAt : Date.now(),
          };
        })
        .filter(function (it) {
          return !!it.lineId && it.end > it.start && !!it.content;
        });
      if (typeof p.backgroundImage !== "string") p.backgroundImage = "";
      if (typeof p.playBackgroundLight !== "string") p.playBackgroundLight = "";
      if (typeof p.playBackgroundDark !== "string") p.playBackgroundDark = "";
      const openingText = String((p.playIntro && p.playIntro.opening) || p.storyStart || "").trim();
      if (p.playTurns.length === 1 && openingText) {
        const onlyTurn = p.playTurns[0] || {};
        const onlyLines = Array.isArray(onlyTurn.lines) ? onlyTurn.lines : [];
        const onlyChoices = Array.isArray(onlyTurn.choices) ? onlyTurn.choices : [];
        if (!onlyChoices.length && onlyLines.length === 1) {
          const firstLine = onlyLines[0] || {};
          const firstText = String(firstLine.text || "").trim();
          const isNarrator = !firstLine.characterId || firstLine.characterId === "narrator";
          if (isNarrator && firstText === openingText) p.playTurns = [];
        }
      }
      if (plotHasRecordedInteractivePlay(p)) p.storyEntered = true;
      if (typeof p.currentTurnIndex !== "number" || !Number.isFinite(p.currentTurnIndex)) p.currentTurnIndex = 0;
    });
    const defC =
      charCategories.find((c) => c.id === "cc-main") ||
      charCategories.find((c) => c.id !== CHAR_CATEGORY_SELF_ID) ||
      charCategories[0];
    if (defC) {
      characters.forEach((c) => {
        if (typeof c.relationships !== "string") {
          if (Array.isArray(c.relations) && c.relations.length) {
            c.relationships = c.relations
              .map((r) => {
                if (!r || !r.otherId) return "";
                const name = characters.find((ch) => ch.id === r.otherId)?.name || "某角色";
                const note = r.note && String(r.note).trim() ? String(r.note).trim() : "";
                return note ? name + "：" + note : name;
              })
              .filter(Boolean)
              .join("\n");
          } else {
            c.relationships = "";
          }
        }
        delete c.relations;
        if (!c.categoryId || !charCategories.some((x) => x.id === c.categoryId)) c.categoryId = defC.id;
      });
    }
  }

